methods.Fs/NodeHelper.php::sanitiseFilename:
function sanitiseFilename(string $name, string $default = 'New File'): string {
		// replace '/' with '-' to prevent directory traversal
		// replacing instead of stripping seems the better tradeoff here
		$name = str_replace('/', '-', $name);

		// remove characters which are illegal on Windows (includes illegal characters on Unix/Linux)
		// see also \OC\Files\Storage\Common::verifyPosixPath(...)
		/** @noinspection CascadeStringReplacementInspection */
		$name = str_replace(['*', '|', '\\', ':', '"', '<', '>', '?'], '', $name);

		// if mysql doesn't support 4byte UTF-8, then remove those characters
		// see \OC\Files\Storage\Common::verifyPath(...)
		if (!$this->db4ByteSupport) {
			$name = preg_replace('%(?:
                \xF0[\x90-\xBF][\x80-\xBF]{2}      # planes 1-3
              | [\xF1-\xF3][\x80-\xBF]{3}          # planes 4-15
              | \xF4[\x80-\x8F][\x80-\xBF]{2}      # plane 16
              )%xs', '', $name);
		}

		// remove leading+trailing spaces and dots to prevent hidden files
		$name = trim($name, ' .');

		if ($name === '') {
			$name = $this->l10n->t($default);
		}

		return $name;
	}

methods.Service/PageService.php::getPageByFile:
function getPageByFile(File $file, ?Node $parent = null): PageInfo {
		try {
			$page = $this->pageMapper->findByFileId($file->getId());
		} catch (InvalidPathException|FilesNotFoundException $e) {
			throw new NotFoundException($e->getMessage(), 0, $e);
		}
		$lastUserId = ($page !== null) ? $page->getLastUserId() : null;
		$emoji = ($page !== null) ? $page->getEmoji() : null;
		$subpageOrder = ($page !== null) ? $page->getSubpageOrder() : null;
		$fullWidth = $page !== null && $page->getFullWidth();
		$slug = ($page !== null) ? $page->getSlug() : null;
		$tags = ($page !== null) ? $page->getTags() : null;
		$linkedPageIds = ($page !== null) ? $this->pageLinkMapper->findByPageId($page->getFileId()) : null;
		$pageInfo = new PageInfo();
		try {
			$pageInfo->fromFile($file,
				$this->getParentPageId($file, $parent),
				$lastUserId,
				$lastUserId ? $this->userManager->getDisplayName($lastUserId) : null,
				$emoji,
				$subpageOrder,
				$fullWidth,
				$slug,
				$tags,
				$linkedPageIds);
		} catch (FilesNotFoundException|InvalidPathException $e) {
			throw new NotFoundException($e->getMessage(), 0, $e);
		}

		return $pageInfo;
	}

