methods.Db/PageMapper.php::findByFileId:
function findByFileId(int $fileId, bool $trashed = false): ?Page {
		$qb = $this->db->getQueryBuilder();
		$andX = [
			$qb->expr()->eq('file_id', $qb->createNamedParameter($fileId, IQueryBuilder::PARAM_INT)),
		];
		if ($trashed) {
			$andX[] = $qb->expr()->isNotNull('trash_timestamp');
		} else {
			$andX[] = $qb->expr()->isNull('trash_timestamp');
		}
		$qb->select('*')
			->from($this->tableName)
			->where($qb->expr()->andX(...$andX));
		try {
			return $this->findEntity($qb);
		} catch (DoesNotExistException|MultipleObjectsReturnedException) {
			return null;
		}
	}

methods.Fs/UserFolderHelper.php::get:
function get(string $userId): Folder {
		$userHomeFolder = $this->rootFolder->getUserFolder($userId);
		$userCollectivesPath = $this->getUserFolderSetting($userId);
		try {
			/** @var Folder $userCollectivesFolder */
			$userCollectivesFolder = $userHomeFolder->get($userCollectivesPath);
		} catch (NotFoundException $e) {
			\OC_Util::setupFS($userId);
			/** @var Folder $userCollectivesFolder */
			$userCollectivesFolder = $userHomeFolder->get($userCollectivesPath);
		}
		return $userCollectivesFolder;
	}

methods.Mount/CollectiveFolderManager.php::getRo:
function getRootPath(): string {
		if ($this->rootPath !== null) {
			return $this->rootPath;
		}

		$this->rootPath = $this->getAppdataPath() . '/collectives';
		return $this->rootPath;
	}

function getRootFolder(): Folder {
		if ($this->collectivesRootFolder !== null) {
			return $this->collectivesRootFolder;
		}

		$rootFolder = $this->rootFolder;
		$appdataPath = $this->getAppdataPath();
		$this->collectivesRootFolder = new LazyFolder($rootFolder, function () use ($rootFolder, $appdataPath) {
			/** @var Folder $appdata */
			$appdata = $rootFolder->get($appdataPath);
			try {
				return $appdata->get('/collectives');
			} catch (NotFoundException) {
				return $appdata->newFolder('collectives');
			}
		}, [
			'path' => '/' . $this->getRootPath(),
		]);

		return $this->collectivesRootFolder;
	}

methods.Mount/CollectiveFolderManager.php::getFo:
function getFolder(int $id): Folder {
		$folder = $this->getRootFolder()->get((string)$id);
		if (!$folder instanceof Folder) {
			throw new InvalidPathException('Not a folder: ' . $folder->getPath());
		}
		return $folder;
	}

methods.Mount/CollectiveFolderManager.php::initi:
function initializeFolder(int $id, string $lang, string $name): Folder {
		$folder = $this->getOrCreateFolder($id);

		$landingPageFileName = self::LANDING_PAGE_TITLE . self::SUFFIX;
		if (!$folder->nodeExists($landingPageFileName)) {
			$content = $this->getLandingPageContent($name, $lang);
			$folder->newFile($landingPageFileName, $content);
		}

		return $folder;
	}

methods.Controller/CollectiveController.php::cre:
function create(string $name, ?string $emoji = null): DataResponse {
		try {
			[$collective, $info] = $this->handleErrorResponse(function () use ($name, $emoji): array {
				[$collective, $info] = $this->service->createCollective(
					$this->getUid(),
					$this->getUserLang(),
					$name,
					$emoji,
				);
				return [$collective, $info];
			}, $this->logger);
		} catch (CircleExistsException|UnprocessableEntityException $e) {
			$this->logger->debug('Collectives app team exists error: ' . $e->getMessage(), ['exception' => $e]);
			throw new OCSBadRequestException($e->getMessage());
		}
		return new DataResponse(['collective' => $collective, 'info' => $info]);
	}

