function getLocalFederatedUser(string $userId, bool $check = true, bool $generate = false): FederatedUser {
		$displayName = $userId;
		if ($check) {
			$user = $this->userManager->get($userId);
			if ($user === null) {
				throw new FederatedUserNotFoundException('user ' . $userId . ' not found');
			}
			$displayName = $this->userManager->getDisplayName($userId);
		} else {
			$accountData = $this->accountRequest->getAccountData($userId);
			if (array_key_exists('displayName', $accountData)) {
				$displayName = $accountData['displayName'];
			}
		}

		$federatedUser = new FederatedUser();
		$federatedUser->set($userId, '', Member::TYPE_USER, $displayName);

		$cached = $this->getCachedLocalFederatedUser($federatedUser);
		if (!$cached) {
			$this->fillSingleCircleId($federatedUser, ($check || $generate));
			$this->userConfig->setValueString($userId, Application::APP_ID, ConfigLexicon::USER_SINGLE_ID, $federatedUser->getSingleId());
		}

		return $federatedUser;
	}

